pub fn git_object_id_text_note() -> String {
    thread_local! {
        static CACHED: String = {
            "THE VALIDATING CONSTRUCTORS. A bare string cast into Sha1Digest or Sha256Digest admits any string: before these existed, a consumer casting text into one could produce a GitSha1ObjectId carrying \"x\", a 64-digit value labelled sha1, or arbitrary non-hex, and every one of those typechecked as a Git object id (review 2026-07-30, on the merge-admission wire parser that did exactly this). Family is not enough — LENGTH and SYNTAX are what make an object id an object id, and they differ per family, which is precisely why the discriminant exists.\n\nThese reuse extdeps.numeric.base16 base16_decode_lower rather than introducing a second hex reader, so the canonical form is one authority: git spells object ids in LOWERCASE hex, and an uppercase or mixed-case spelling refuses rather than being folded, because folding would make two textual forms name one object and quietly break the round trip. A caller holding a foreign-cased id normalizes deliberately at its own boundary.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

