pub fn git_unavailable_object_index_step(state: Rc<GitUnavailableObjectIndexOutcome>, unavailable: Rc<GitUnavailableObject>) -> Rc<GitUnavailableObjectIndexOutcome> {
    match (*state.clone()).clone() {
    GitUnavailableObjectIndexOutcome::GitUnavailableObjectIndexDuplicate { oid: oid, .. } => Rc::new(GitUnavailableObjectIndexOutcome::GitUnavailableObjectIndexDuplicate {
    oid: oid.clone(),
}),
    GitUnavailableObjectIndexOutcome::GitUnavailableObjectIndexReady { index: index, .. } => {
        let oid = git_unavailable_object_oid(unavailable.clone());
if v1_rt::map_contains_key(&index, oid.clone()) {
            Rc::new(GitUnavailableObjectIndexOutcome::GitUnavailableObjectIndexDuplicate {
    oid: oid.clone(),
})
        } else {
            Rc::new(GitUnavailableObjectIndexOutcome::GitUnavailableObjectIndexReady {
    index: v1_rt::rc_map_insert(index.clone(), oid.clone(), unavailable.clone()),
})
        }
},
}
}

pub fn git_unavailable_object_index(unavailable: Rc<Vec<Rc<GitUnavailableObject>>>) -> Rc<GitUnavailableObjectIndexOutcome> {
    unavailable.iter().cloned().fold(Rc::new(GitUnavailableObjectIndexOutcome::GitUnavailableObjectIndexReady {
    index: v1_rt::rc_empty_map::<_, _>(),
}), git_unavailable_object_index_step)
}

