pub fn git_decode_tree_mode(text: String) -> Rc<GitTreeModeDecodeOutcome> {
    if (text.clone() == "100644".to_string()) {
        Rc::new(GitTreeModeDecodeOutcome::GitTreeModeDecoded {
    mode: GitTreeMode::GitRegularBlobMode,
})
    } else {
        if (text.clone() == "100755".to_string()) {
            Rc::new(GitTreeModeDecodeOutcome::GitTreeModeDecoded {
    mode: GitTreeMode::GitExecutableBlobMode,
})
        } else {
            if (text.clone() == "120000".to_string()) {
                Rc::new(GitTreeModeDecodeOutcome::GitTreeModeDecoded {
    mode: GitTreeMode::GitSymlinkMode,
})
            } else {
                if (text.clone() == "040000".to_string()) {
                    Rc::new(GitTreeModeDecodeOutcome::GitTreeModeDecoded {
    mode: GitTreeMode::GitSubtreeMode,
})
                } else {
                    if (text.clone() == "160000".to_string()) {
                        Rc::new(GitTreeModeDecodeOutcome::GitTreeModeDecoded {
    mode: GitTreeMode::GitlinkMode,
})
                    } else {
                        Rc::new(GitTreeModeDecodeOutcome::GitTreeModeRefused)
                    }
                }
            }
        }
    }
}

pub fn git_encode_tree_mode(mode: GitTreeMode) -> String {
    match mode.clone() {
    GitTreeMode::GitRegularBlobMode => "100644".to_string(),
    GitTreeMode::GitExecutableBlobMode => "100755".to_string(),
    GitTreeMode::GitSymlinkMode => "120000".to_string(),
    GitTreeMode::GitSubtreeMode => "040000".to_string(),
    GitTreeMode::GitlinkMode => "160000".to_string(),
}
}

pub fn git_tree_mode_object_type(mode: GitTreeMode) -> String {
    match mode.clone() {
    GitTreeMode::GitRegularBlobMode => "blob".to_string(),
    GitTreeMode::GitExecutableBlobMode => "blob".to_string(),
    GitTreeMode::GitSymlinkMode => "blob".to_string(),
    GitTreeMode::GitSubtreeMode => "tree".to_string(),
    GitTreeMode::GitlinkMode => "commit".to_string(),
}
}

pub fn git_tree_entry_from_mode(mode: GitTreeMode, name: Rc<GitTreeEntryName>, oid: Rc<GitObjectId>) -> Rc<TreeEntry> {
    match mode.clone() {
    GitTreeMode::GitRegularBlobMode => Rc::new(TreeEntry::RegularBlobEntry {
    name: name.clone(),
    oid: oid.clone(),
}),
    GitTreeMode::GitExecutableBlobMode => Rc::new(TreeEntry::ExecutableBlobEntry {
    name: name.clone(),
    oid: oid.clone(),
}),
    GitTreeMode::GitSymlinkMode => Rc::new(TreeEntry::SymlinkEntry {
    name: name.clone(),
    oid: oid.clone(),
}),
    GitTreeMode::GitSubtreeMode => Rc::new(TreeEntry::SubtreeEntry {
    name: name.clone(),
    oid: oid.clone(),
}),
    GitTreeMode::GitlinkMode => Rc::new(TreeEntry::GitlinkEntry {
    name: name.clone(),
    oid: oid.clone(),
}),
}
}

pub fn git_decode_tree_entry(entry: Rc<GitTreeWireEntry>) -> Rc<GitTreeEntryDecodeOutcome> {
    match (*git_decode_tree_entry_name(entry.name.clone())).clone() {
    GitTreeEntryNameDecodeOutcome::GitTreeEntryNameDecodeRefused { cause: cause, .. } => Rc::new(GitTreeEntryDecodeOutcome::GitTreeEntryDecodeRefused {
    cause: Rc::new(GitTreeDecodeRefusal::GitTreeEntryNameRefused {
    name: entry.name.clone(),
    cause: cause.clone(),
}),
}),
    GitTreeEntryNameDecodeOutcome::GitTreeEntryNameDecoded { name: name, .. } => match (*git_decode_tree_mode(entry.mode.clone())).clone() {
    GitTreeModeDecodeOutcome::GitTreeModeRefused => Rc::new(GitTreeEntryDecodeOutcome::GitTreeEntryDecodeRefused {
    cause: Rc::new(GitTreeDecodeRefusal::GitTreeModeObjectMismatch {
    mode: entry.mode.clone(),
    object_type: entry.object_type.clone(),
    name: entry.name.clone(),
}),
}),
    GitTreeModeDecodeOutcome::GitTreeModeDecoded { mode: mode, .. } => if (git_tree_mode_object_type(mode.clone()) == entry.object_type.clone()) {
        Rc::new(GitTreeEntryDecodeOutcome::GitTreeEntryDecoded {
    entry: git_tree_entry_from_mode(mode.clone(), name.clone(), entry.oid.clone()),
})
    } else {
        Rc::new(GitTreeEntryDecodeOutcome::GitTreeEntryDecodeRefused {
    cause: Rc::new(GitTreeDecodeRefusal::GitTreeModeObjectMismatch {
    mode: entry.mode.clone(),
    object_type: entry.object_type.clone(),
    name: entry.name.clone(),
}),
})
    },
},
}
}

pub fn git_decode_tree_step(state: Rc<GitTreeDecodeOutcome>, wire: Rc<GitTreeWireEntry>) -> Rc<GitTreeDecodeOutcome> {
    match (*state.clone()).clone() {
    GitTreeDecodeOutcome::GitTreeDecodeRefused { cause: cause, .. } => Rc::new(GitTreeDecodeOutcome::GitTreeDecodeRefused {
    cause: cause.clone(),
}),
    GitTreeDecodeOutcome::GitTreeDecoded { entries: entries, .. } => match (*git_decode_tree_entry(wire)).clone() {
    GitTreeEntryDecodeOutcome::GitTreeEntryDecoded { entry: entry, .. } => Rc::new(GitTreeDecodeOutcome::GitTreeDecoded {
    entries: v1_rt::rc_list_concat(entries.clone(), Rc::new(vec![entry.clone()])),
}),
    GitTreeEntryDecodeOutcome::GitTreeEntryDecodeRefused { cause: cause, .. } => Rc::new(GitTreeDecodeOutcome::GitTreeDecodeRefused {
    cause: cause.clone(),
}),
},
}
}

pub fn git_decode_tree(entries: Rc<Vec<Rc<GitTreeWireEntry>>>) -> Rc<GitTreeDecodeOutcome> {
    entries.iter().cloned().fold(Rc::new(GitTreeDecodeOutcome::GitTreeDecoded {
    entries: Rc::new(vec![]),
}), git_decode_tree_step)
}

