pub fn git_nul_record_split_octet_step(state: Rc<GitNulRecordSplitState>, octet: UInt8) -> Rc<GitNulRecordSplitState> {
    match (*state.clone()).clone() {
    GitNulRecordSplitState::GitNulRecordSplitRefused { cause: cause, .. } => Rc::new(GitNulRecordSplitState::GitNulRecordSplitRefused {
    cause: cause.clone(),
}),
    GitNulRecordSplitState::GitNulRecordSplitAwaitFirstSpace { first: first, .. } => if (octet.clone() == 32) {
        if ((first.clone().len() as i64) == 0) {
            Rc::new(GitNulRecordSplitState::GitNulRecordSplitRefused {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetEmptyField),
})
        } else {
            Rc::new(GitNulRecordSplitState::GitNulRecordSplitAwaitSecondSpace {
    first: first.clone(),
    second: Rc::new(vec![]),
})
        }
    } else {
        Rc::new(GitNulRecordSplitState::GitNulRecordSplitAwaitFirstSpace {
    first: v1_rt::rc_list_concat(first.clone(), Rc::new(vec![octet.clone()])),
})
    },
    GitNulRecordSplitState::GitNulRecordSplitAwaitSecondSpace { first, second, .. } => if (octet.clone() == 32) {
        if ((second.clone().len() as i64) == 0) {
            Rc::new(GitNulRecordSplitState::GitNulRecordSplitRefused {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetEmptyField),
})
        } else {
            Rc::new(GitNulRecordSplitState::GitNulRecordSplitAwaitTab {
    first: first.clone(),
    second: second.clone(),
    third: Rc::new(vec![]),
})
        }
    } else {
        Rc::new(GitNulRecordSplitState::GitNulRecordSplitAwaitSecondSpace {
    first: first.clone(),
    second: v1_rt::rc_list_concat(second.clone(), Rc::new(vec![octet.clone()])),
})
    },
    GitNulRecordSplitState::GitNulRecordSplitAwaitTab { first, second, third, .. } => if (octet.clone() == 9) {
        if ((third.clone().len() as i64) == 0) {
            Rc::new(GitNulRecordSplitState::GitNulRecordSplitRefused {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetEmptyField),
})
        } else {
            Rc::new(GitNulRecordSplitState::GitNulRecordSplitFourth {
    first: first.clone(),
    second: second.clone(),
    third: third.clone(),
    fourth: Rc::new(vec![]),
})
        }
    } else {
        Rc::new(GitNulRecordSplitState::GitNulRecordSplitAwaitTab {
    first: first.clone(),
    second: second.clone(),
    third: v1_rt::rc_list_concat(third.clone(), Rc::new(vec![octet.clone()])),
})
    },
    GitNulRecordSplitState::GitNulRecordSplitFourth { first, second, third, fourth, .. } => Rc::new(GitNulRecordSplitState::GitNulRecordSplitFourth {
    first: first.clone(),
    second: second.clone(),
    third: third.clone(),
    fourth: v1_rt::rc_list_concat(fourth.clone(), Rc::new(vec![octet.clone()])),
}),
}
}

