pub fn git_split_nul_record_quartet(record: Rc<Vec<UInt8>>) -> Rc<GitNulRecordSplitOutcome> {
    match (*record.iter().cloned().fold(Rc::new(GitNulRecordSplitState::GitNulRecordSplitAwaitFirstSpace {
    first: Rc::new(vec![]),
}), git_nul_record_split_octet_step)).clone() {
    GitNulRecordSplitState::GitNulRecordSplitRefused { cause: cause, .. } => Rc::new(GitNulRecordSplitOutcome::GitNulRecordSplitRefusedOutcome {
    cause: cause.clone(),
}),
    GitNulRecordSplitState::GitNulRecordSplitFourth { first, second, third, fourth, .. } => if ((fourth.clone().len() as i64) == 0) {
        Rc::new(GitNulRecordSplitOutcome::GitNulRecordSplitRefusedOutcome {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetEmptyField),
})
    } else {
        Rc::new(GitNulRecordSplitOutcome::GitNulRecordSplitDecoded {
    quartet: Rc::new(GitNulQuartet {
    first: first.clone(),
    second: second.clone(),
    third: third.clone(),
    fourth: fourth.clone(),
}),
})
    },
    GitNulRecordSplitState::GitNulRecordSplitAwaitFirstSpace { first: _, .. } => Rc::new(GitNulRecordSplitOutcome::GitNulRecordSplitRefusedOutcome {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetIncompleteRecord {
    field_count: 0,
}),
}),
    GitNulRecordSplitState::GitNulRecordSplitAwaitSecondSpace { .. } => Rc::new(GitNulRecordSplitOutcome::GitNulRecordSplitRefusedOutcome {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetIncompleteRecord {
    field_count: 1,
}),
}),
    GitNulRecordSplitState::GitNulRecordSplitAwaitTab { .. } => Rc::new(GitNulRecordSplitOutcome::GitNulRecordSplitRefusedOutcome {
    cause: Rc::new(GitNulQuartetRefusal::GitNulQuartetIncompleteRecord {
    field_count: 2,
}),
}),
}
}

