pub fn git_decode_object_id_text(format: GitObjectFormat, text: String) -> Rc<GitObjectIdTextDecodeOutcome> {
    {
        let expected_length = match format.clone() {
    GitObjectFormat::GitObjectFormatSha1 => 40,
    GitObjectFormat::GitObjectFormatSha256 => 64,
};
if (v1_rt::string_length(&text) != expected_length.clone()) {
            Rc::new(GitObjectIdTextDecodeOutcome::GitObjectIdTextRefused {
    cause: Rc::new(GitObjectIdTextRefusal::GitObjectIdTextWrongLength {
    format: format.clone(),
    observed: v1_rt::string_length(&text),
}),
})
        } else {
            if !{ let mut __all = true; for cp in v1_rt::chars(&text).iter().cloned() { if !(crate::extdeps_numeric_base16::base16_is_digit_code_point(cp.clone())) { __all = false; break; } } __all } {
                Rc::new(GitObjectIdTextDecodeOutcome::GitObjectIdTextRefused {
    cause: Rc::new(GitObjectIdTextRefusal::GitObjectIdTextNonHexadecimal),
})
            } else {
                if { let mut __found = false; for cp in v1_rt::chars(&text).iter().cloned() { if crate::extdeps_numeric_base16::base16_is_upper_digit_code_point(cp.clone()) { __found = true; break; } } __found } {
                    Rc::new(GitObjectIdTextDecodeOutcome::GitObjectIdTextRefused {
    cause: Rc::new(GitObjectIdTextRefusal::GitObjectIdTextNonCanonicalUppercase),
})
                } else {
                    match format.clone() {
    GitObjectFormat::GitObjectFormatSha1 => Rc::new(GitObjectIdTextDecodeOutcome::GitObjectIdTextDecoded {
    oid: Rc::new(GitObjectId::GitSha1ObjectId {
    digest: Rc::new(Sha1Digest {
    hex: text.clone(),
}),
}),
}),
    GitObjectFormat::GitObjectFormatSha256 => Rc::new(GitObjectIdTextDecodeOutcome::GitObjectIdTextDecoded {
    oid: Rc::new(GitObjectId::GitSha256ObjectId {
    digest: Rc::new(Sha256Digest {
    hex: text.clone(),
}),
}),
}),
}
                }
            }
        }
}
}

