pub fn git_ascii_field_text(octets: Rc<Vec<UInt8>>) -> Option<String> {
    if !{ let mut __all = true; for octet in octets.iter().cloned() { if !((octet.clone() != 0)) { __all = false; break; } } __all } {
        std::option::Option::None
    } else {
        match (*crate::std_encoding::ascii_decode_octets(octets.clone())).clone() {
    AsciiDecodeOutcome::AsciiDecoded { text: text, .. } => Some(text.clone()),
    AsciiDecodeOutcome::AsciiNonAscii { .. } => std::option::Option::None,
}
    }
}

pub fn git_ls_tree_z_row_step(state: Rc<GitLsTreeZDecodeOutcome>, row: Rc<GitNulQuartet>, format: GitObjectFormat) -> Rc<GitLsTreeZDecodeOutcome> {
    match (*state.clone()).clone() {
    GitLsTreeZDecodeOutcome::GitLsTreeZRefused { cause: cause, .. } => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: cause.clone(),
}),
    GitLsTreeZDecodeOutcome::GitLsTreeZDecoded { entries: entries, .. } => match git_ascii_field_text(row.first.clone()) {
    std::option::Option::None => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: Rc::new(GitLsTreeZRefusal::GitLsTreeZHeaderNonAscii {
    field: "mode".to_string(),
}),
}),
    Some(mode) => match git_ascii_field_text(row.second.clone()) {
    std::option::Option::None => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: Rc::new(GitLsTreeZRefusal::GitLsTreeZHeaderNonAscii {
    field: "object-type".to_string(),
}),
}),
    Some(object_type) => match git_ascii_field_text(row.third.clone()) {
    std::option::Option::None => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: Rc::new(GitLsTreeZRefusal::GitLsTreeZHeaderNonAscii {
    field: "object-id".to_string(),
}),
}),
    Some(object_id_text) => match (*git_decode_object_id_text(format, object_id_text.clone())).clone() {
    GitObjectIdTextDecodeOutcome::GitObjectIdTextRefused { cause: cause, .. } => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: Rc::new(GitLsTreeZRefusal::GitLsTreeZObjectIdRefused {
    cause: cause.clone(),
}),
}),
    GitObjectIdTextDecodeOutcome::GitObjectIdTextDecoded { oid: oid, .. } => {
        let wire = Rc::new(GitTreeWireEntry {
    mode: mode.clone(),
    object_type: object_type.clone(),
    oid: oid.clone(),
    name: Rc::new(GitTreeWireName {
    octets: row.fourth.clone(),
}),
});
match (*git_decode_tree_entry(wire.clone())).clone() {
    GitTreeEntryDecodeOutcome::GitTreeEntryDecodeRefused { cause: cause, .. } => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: Rc::new(GitLsTreeZRefusal::GitLsTreeZEntryRefused {
    cause: cause.clone(),
}),
}),
    GitTreeEntryDecodeOutcome::GitTreeEntryDecoded { entry: _, .. } => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZDecoded {
    entries: v1_rt::rc_list_concat(entries.clone(), Rc::new(vec![wire.clone()])),
}),
}
},
},
},
},
},
}
}

pub fn git_decode_ls_tree_z(payload: Vec<u8>, format: GitObjectFormat) -> Rc<GitLsTreeZDecodeOutcome> {
    match (*git_decode_nul_quartets(payload)).clone() {
    GitNulQuartetDecodeOutcome::GitNulQuartetsRefused { cause: cause, .. } => Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZRefused {
    cause: Rc::new(GitLsTreeZRefusal::GitLsTreeZFramingRefused {
    cause: cause.clone(),
}),
}),
    GitNulQuartetDecodeOutcome::GitNulQuartetsDecoded { rows: rows, .. } => rows.iter().cloned().fold(Rc::new(GitLsTreeZDecodeOutcome::GitLsTreeZDecoded {
    entries: Rc::new(vec![]),
}), |state: Rc<GitLsTreeZDecodeOutcome>, row: Rc<GitNulQuartet>| git_ls_tree_z_row_step(state, row.clone(), format.clone())),
}
}

