pub fn git_decode_index_stage(text: String) -> Rc<GitIndexStageDecodeOutcome> {
    if (text.clone() == "0".to_string()) {
        Rc::new(GitIndexStageDecodeOutcome::GitIndexStageDecoded {
    stage: GitIndexStage::GitIndexStageNormal,
})
    } else {
        if (text.clone() == "1".to_string()) {
            Rc::new(GitIndexStageDecodeOutcome::GitIndexStageDecoded {
    stage: GitIndexStage::GitIndexStageBase,
})
        } else {
            if (text.clone() == "2".to_string()) {
                Rc::new(GitIndexStageDecodeOutcome::GitIndexStageDecoded {
    stage: GitIndexStage::GitIndexStageOurs,
})
            } else {
                if (text.clone() == "3".to_string()) {
                    Rc::new(GitIndexStageDecodeOutcome::GitIndexStageDecoded {
    stage: GitIndexStage::GitIndexStageTheirs,
})
                } else {
                    Rc::new(GitIndexStageDecodeOutcome::GitIndexStageRefused {
    text: text.clone(),
})
                }
            }
        }
    }
}

