pub fn git_project_tree_entry(entry: Rc<TreeEntry>) -> Rc<GitTreeWireEntry> {
    match (*entry.clone()).clone() {
    TreeEntry::RegularBlobEntry { name, oid, .. } => Rc::new(GitTreeWireEntry {
    mode: "100644".to_string(),
    object_type: "blob".to_string(),
    oid: oid.clone(),
    name: Rc::new(GitTreeWireName {
    octets: git_tree_entry_name_octets(name.clone()),
}),
}),
    TreeEntry::ExecutableBlobEntry { name, oid, .. } => Rc::new(GitTreeWireEntry {
    mode: "100755".to_string(),
    object_type: "blob".to_string(),
    oid: oid.clone(),
    name: Rc::new(GitTreeWireName {
    octets: git_tree_entry_name_octets(name.clone()),
}),
}),
    TreeEntry::SymlinkEntry { name, oid, .. } => Rc::new(GitTreeWireEntry {
    mode: "120000".to_string(),
    object_type: "blob".to_string(),
    oid: oid.clone(),
    name: Rc::new(GitTreeWireName {
    octets: git_tree_entry_name_octets(name.clone()),
}),
}),
    TreeEntry::SubtreeEntry { name, oid, .. } => Rc::new(GitTreeWireEntry {
    mode: "040000".to_string(),
    object_type: "tree".to_string(),
    oid: oid.clone(),
    name: Rc::new(GitTreeWireName {
    octets: git_tree_entry_name_octets(name.clone()),
}),
}),
    TreeEntry::GitlinkEntry { name, oid, .. } => Rc::new(GitTreeWireEntry {
    mode: "160000".to_string(),
    object_type: "commit".to_string(),
    oid: oid.clone(),
    name: Rc::new(GitTreeWireName {
    octets: git_tree_entry_name_octets(name.clone()),
}),
}),
}
}

pub fn git_project_tree(tree: Rc<Tree>) -> Rc<Vec<Rc<GitTreeWireEntry>>> {
    Rc::new({ let mut __result = Vec::new(); for entry in tree.entries.clone().iter().cloned() { __result.push(git_project_tree_entry(entry.clone())); } __result })
}

