pub fn git_model_update_ref_exact_after_repository_decode(repo: Rc<GitRepositoryState>, name: NonEmptyStr, new_oid: Rc<GitObjectId>, expected_old: Rc<GitObjectId>) -> Rc<GitUpdateRefOutcome> {
    if !(git_object_id_format(new_oid.clone()) == repo.object_format.clone()) {
        Rc::new(GitUpdateRefOutcome::GitRefAdvanceFormatMismatch {
    repository: repo.clone(),
    repository_format: repo.object_format.clone(),
    oid: new_oid.clone(),
})
    } else {
        if !(git_object_id_format(expected_old.clone()) == repo.object_format.clone()) {
            Rc::new(GitUpdateRefOutcome::GitRefAdvanceFormatMismatch {
    repository: repo.clone(),
    repository_format: repo.object_format.clone(),
    oid: expected_old.clone(),
})
        } else {
            match (*git_lookup_object_after_repository_decode(repo.clone(), new_oid.clone())).clone() {
    ObjectLookupResult::ObjectFound { stored: new_object, .. } => git_model_update_ref_exact_dereferenced(repo.clone(), name.clone(), name.clone(), Rc::new(vec![]), new_oid.clone(), expected_old.clone(), store_object_kind(new_object.object.clone())),
    unavailable => { let unavailable = Rc::new(unavailable.clone()); Rc::new(GitUpdateRefOutcome::GitRefAdvanceTargetUnavailable {
    repository: repo.clone(),
    oid: new_oid.clone(),
    lookup: unavailable.clone(),
}) },
}
        }
    }
}

pub fn git_model_update_ref_exact(repo: Rc<GitRepositoryState>, name: NonEmptyStr, new_oid: Rc<GitObjectId>, expected_old: Rc<GitObjectId>) -> Rc<GitUpdateRefOutcome> {
    match (*git_decode_repository(repo.clone())).clone() {
    GitRepositoryDecodeOutcome::GitRepositoryDecodeRefused { cause: cause, .. } => Rc::new(GitUpdateRefOutcome::GitRefAdvanceRepositoryInvalid {
    repository: repo.clone(),
    cause: cause.clone(),
}),
    GitRepositoryDecodeOutcome::GitRepositoryDecoded { repository: repository, .. } => git_model_update_ref_exact_after_repository_decode(repository.clone(), name, new_oid, expected_old),
}
}

